const body = $input.first().json.body;
if (body.commandName !== 'giveaway') {
  return [{ json: { skip: true } }];
}
const staticData = $getWorkflowStaticData('global');
staticData.giveaways = staticData.giveaways || {};

const prize = body.options.prize;
const durationMin = body.options.duration_minutes;
const winners = body.options.winners || 1;
const endsAt = Date.now() + durationMin * 60 * 1000;
const giveawayId = `gw-${Date.now().toString(36)}`;

return [{ json: { giveawayId, prize, durationMin, winners, endsAt, channelId: body.channelId, hostId: body.user.id, hostName: body.user.displayName, interactionToken: body.interactionToken, applicationId: body.applicationId } }];

