parameters.jsCode:
const messageId = $input.first().json && $('Discord: post giveaway').first().json.id;
const gw = $('Build giveaway data').first().json;
const staticData = $getWorkflowStaticData('global');
staticData.giveaways = staticData.giveaways || {};
staticData.giveaways[gw.giveawayId] = {
  messageId,
  channelId: gw.channelId,
  prize: gw.prize,
  winners: gw.winners,
  endsAt: gw.endsAt,
  hostId: gw.hostId,
  done: false,
};
return [{ json: { saved: true, gw: staticData.giveaways[gw.giveawayId], applicationId: gw.applicationId, interactionToken: gw.interactionToken } }];

const staticData = $getWorkflowStaticData('global');
const giveaways = staticData.giveaways || {};
const now = Date.now();
const ready = Object.entries(giveaways)
  .filter(([_, g]) => !g.done && now >= g.endsAt)
  .map(([id, g]) => ({ giveawayId: id, ...g }));
if (ready.length === 0) return [];
return ready.map(r => ({ json: r }));

const reactors = ($input.first().json || []).filter(u => !u.bot);
const gw = $('Find ended giveaways').first().json;
if (reactors.length === 0) {
  const sd = $getWorkflowStaticData('global');
  sd.giveaways[gw.giveawayId].done = true;
  return [{ json: { ...gw, winners: [], noEntrants: true } }];
}
const shuffled = reactors.sort(() => Math.random() - 0.5);
const winnerCount = Math.min(gw.winners || 1, shuffled.length);
const winners = shuffled.slice(0, winnerCount);
const sd = $getWorkflowStaticData('global');
sd.giveaways[gw.giveawayId].done = true;
return [{ json: { ...gw, winners, noEntrants: false } }];

parameters.jsonBody:
={
  "content": $json.noEntrants ? `❌ انتهى سحب **${$json.prize}** بدون مشاركين.` : `🎉 الفائزون بـ **${$json.prize}**: ${$json.winners.map(w => `<@${w.id}>`).join(', ')}\n\n👏 مبروك! ${$json.winners.length > 1 ? 'كل واحد منكم تواصل مع' : 'تواصل مع'} <@${$json.hostId}> لاستلام جائزتك.`,
  "message_reference": { "message_id": $json.messageId, "fail_if_not_exists": false },
  "allowed_mentions": { "users": [$json.hostId, ...($json.winners || []).map(w => w.id)] }
}
